using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: Discriminator property renamed to "$type".
        // Preserve EF8 property name for compatibility with existing 500K documents.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 breaking change: id format changed from "EntityType|Key" to just "Key".
        // Preserve EF8 id format so existing documents remain addressable.
        modelBuilder.Entity<Product>().HasKey(p => p.Id);
        modelBuilder.Entity<Product>().Property(p => p.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        modelBuilder.Entity<Product>().HasIndex(p => p.Sku);
        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}

// Generates ids in the EF8 format "Product|<key>" for backward compatibility.
class LegacyCosmosIdGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => $"Product|{entry.Property("Id").CurrentValue}";

    public override bool GeneratesTemporaryValues => false;
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

